#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char main_out[OUT_BUF_SIZE];

static void to_camel(const char *src)
{
    size_t out_idx = 0;
    int capitalize_next = 0;
    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];
        if (ch == '_') {
            capitalize_next = 1;
            continue;
        }
        if (capitalize_next && isalpha((unsigned char)ch)) {
            ch = (char)toupper((unsigned char)ch);
            capitalize_next = 0;
        } else {
            ch = (char)tolower((unsigned char)ch);
        }
        main_out[out_idx++] = ch;
    }
    main_out[out_idx] = '\0';
}

static void to_snake(const char *src)
{
    size_t out_idx = 0;
    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];
        if (isupper((unsigned char)ch)) {
            if (i != 0) {
                main_out[out_idx++] = '_';
                if (out_idx >= OUT_BUF_SIZE) break;
            }
            ch = (char)tolower((unsigned char)ch);
        }
        main_out[out_idx++] = ch;
    }
    main_out[out_idx] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
